// Mongoose schemas and models: the shape of each collection (products, users, cart items, orders) and its indexes.
// Connecting to the database is lib/database.js; reading and writing is the other files in models/.

const crypto = require('crypto');
const mongoose = require('mongoose');

// Ids are generated by the app (UUIDs) instead of by MongoDB
const uuid = () => crypto.randomUUID();
// ids are UUID strings (not ObjectIds), so URLs stay the same and invalid ids never throw cast errors
const id = { type: String, default: uuid };

// case-insensitive matching for product titles (used by the unique index and by every title query)
const CI = { locale: 'en', strength: 2 };

// id is the primary (unique) key; title is the unique business key that identifies duplicate products
// One document per product
const productSchema = new mongoose.Schema({
  _id: id,
  title: { type: String, required: true, trim: true },
  price: { type: Number, required: true },
  imageUrl: { type: String, default: '' },
}, { timestamps: { createdAt: true, updatedAt: false } });
productSchema.index({ title: 1 }, { unique: true, collation: CI });

// One document per account, identified by its email address (stored lower-case, so the match ignores case).
// No role is stored: the admin is the account whose email is ADMIN_EMAIL (see services/auth.js).
// passwordHash = scrypt(password, salt) with a random salt per user; the password itself is never stored.
const userSchema = new mongoose.Schema({
  _id: id,
  email: { type: String, required: true, trim: true, lowercase: true },
  salt: { type: String, required: true },
  passwordHash: { type: String, required: true },
}, { timestamps: { createdAt: true, updatedAt: false } });

// One document per (user, product) pair in a cart, with a quantity
// unique, but only among documents that have an email: accounts made by older versions have none, and
// without this filter two of them would count as duplicates of each other
userSchema.index({ email: 1 }, { unique: true, partialFilterExpression: { email: { $type: 'string' } } });

const cartItemSchema = new mongoose.Schema({
  userId: { type: String, required: true },
  productId: { type: String, required: true },
  qty: { type: Number, required: true, default: 1 },
}, { versionKey: false });
cartItemSchema.index({ userId: 1, productId: 1 }, { unique: true });
cartItemSchema.index({ productId: 1 });

// items are embedded snapshots (title/price/qty) so later product edits or deletes don't rewrite history
// One document per placed order
const orderSchema = new mongoose.Schema({
  _id: id,
  userId: { type: String, required: true, index: true },
  total: { type: Number, required: true },
  placedAt: { type: Date, default: Date.now },
  items: [{ _id: false, title: String, price: Number, qty: Number }],
}, { versionKey: false });

// Compile the schemas into models; each maps to one collection
// One document per live login session. _id is the session id from the cookie. data is the session itself,
// encrypted (see lib/seal.js and models/sessionStore.js), so no name or role is readable here. userId is an opaque
// id kept as its own field so all of one user's sessions can be found (to sign them out). MongoDB deletes a
// session once its expires time passes (the TTL index), which is what ends a "keep me signed in" login.
const sessionSchema = new mongoose.Schema({
  _id: { type: String },
  userId: { type: String, default: null, index: true },
  data: { type: String, required: true },
  expires: { type: Date, required: true },
}, { versionKey: false });
sessionSchema.index({ expires: 1 }, { expireAfterSeconds: 0 });

// One document per rate-limit window. _id is "<limiter>:<who>", count is the requests so far in the window and
// resetAt is when the window ends (MongoDB deletes expired ones). Kept in the database rather than in memory so the
// limits hold across restarts and across several server processes.
const rateLimitSchema = new mongoose.Schema({
  _id: { type: String },
  count: { type: Number, required: true },
  resetAt: { type: Date, required: true },
}, { versionKey: false });
rateLimitSchema.index({ resetAt: 1 }, { expireAfterSeconds: 0 });

const Product = mongoose.model('Product', productSchema);
const User = mongoose.model('User', userSchema);
const CartItem = mongoose.model('CartItem', cartItemSchema);
const Order = mongoose.model('Order', orderSchema);
const Session = mongoose.model('Session', sessionSchema);
const RateLimit = mongoose.model('RateLimit', rateLimitSchema);

module.exports = { CI, User, Product, CartItem, Order, Session, RateLimit };
